<?php
require_once '../config/db.php';if(session_status()===PHP_SESSION_NONE)session_start();if(!isset($_SESSION['user_id']))redirect('../index.php');$error='';
try{if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();
 if(isset($_POST['save_field'])){$id=(int)($_POST['field_id']??0);$label=trim((string)$_POST['label']);$key=strtolower(trim((string)($_POST['field_key']?:preg_replace('/[^a-z0-9]+/i','_',$label)),'_'));$type=in_array($_POST['field_type'],['text','textarea','number','date'],true)?$_POST['field_type']:'text';if($label===''||$key==='')throw new RuntimeException('Field label is required.');if($id)$pdo->prepare('UPDATE account_field_definitions SET label=?,field_key=?,field_type=?,sort_order=? WHERE id=?')->execute([$label,$key,$type,(int)$_POST['sort_order'],$id]);else $pdo->prepare('INSERT INTO account_field_definitions(label,field_key,field_type,sort_order) VALUES(?,?,?,?)')->execute([$label,$key,$type,(int)$_POST['sort_order']]);redirect('accounts.php?saved=field');}
 if(isset($_POST['delete_field'])){$pdo->prepare('DELETE FROM account_field_definitions WHERE id=?')->execute([(int)$_POST['field_id']]);redirect('accounts.php?saved=field');}
 if(isset($_POST['save_account'])){$id=(int)($_POST['account_id']??0);$name=trim((string)$_POST['account_name']);$type=in_array($_POST['account_type'],['bank','cash','mobile_money'],true)?$_POST['account_type']:'bank';if($name==='')throw new RuntimeException('Account name is required.');$ledgerCode=$type==='cash'?'1000':'1010';$s=$pdo->prepare('SELECT id FROM chart_of_accounts WHERE account_code=?');$s->execute([$ledgerCode]);$ledger=$s->fetchColumn();$pdo->beginTransaction();if($id){$pdo->prepare('UPDATE accounts SET ledger_account_id=?,account_name=?,account_type=?,is_active=? WHERE id=?')->execute([$ledger,$name,$type,isset($_POST['is_active'])?1:0,$id]);}else{$pdo->prepare('INSERT INTO accounts(ledger_account_id,account_name,account_type,current_balance,is_active) VALUES(?,?,?,?,1)')->execute([$ledger,$name,$type,(float)$_POST['initial_balance']]);$id=(int)$pdo->lastInsertId();}$vs=$pdo->prepare('INSERT INTO account_field_values(account_id,field_definition_id,field_value) VALUES(?,?,?) ON DUPLICATE KEY UPDATE field_value=VALUES(field_value)');foreach(($_POST['custom_field']??[]) as $fieldId=>$value)$vs->execute([$id,(int)$fieldId,trim((string)$value)]);$pdo->commit();redirect('accounts.php?saved=account');}
 }}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e instanceof PDOException&&$e->getCode()==='23000'?'Field key must be unique.':$e->getMessage();}
$fields=$pdo->query('SELECT * FROM account_field_definitions WHERE is_active=1 ORDER BY sort_order,id')->fetchAll();$editId=(int)($_GET['edit']??0);$edit=[];$values=[];if($editId){$s=$pdo->prepare('SELECT * FROM accounts WHERE id=?');$s->execute([$editId]);$edit=$s->fetch()?:[];$s=$pdo->prepare('SELECT field_definition_id,field_value FROM account_field_values WHERE account_id=?');$s->execute([$editId]);foreach($s->fetchAll() as $v)$values[$v['field_definition_id']]=$v['field_value'];}$accounts=$pdo->query("SELECT a.*,GROUP_CONCAT(CONCAT(f.label,'::',REPLACE(REPLACE(COALESCE(v.field_value,''),'|',' '),'::',':')) ORDER BY f.sort_order SEPARATOR '|') custom_values FROM accounts a LEFT JOIN account_field_values v ON v.account_id=a.id LEFT JOIN account_field_definitions f ON f.id=v.field_definition_id GROUP BY a.id ORDER BY a.account_type,a.account_name")->fetchAll();$total=array_sum(array_column(array_filter($accounts,fn($a)=>$a['is_active']),'current_balance'));require_once 'includes/header.php';require_once 'includes/sidebar.php';$input='mt-1 w-full border rounded-lg px-3 py-2.5';
?>
<main class="flex-1 h-screen overflow-y-auto app-scroll"><header class="bg-white border-b px-5 md:px-8 py-5 flex justify-between items-center sticky top-0 z-10"><div class="flex gap-4 items-center"><button data-sidebar-toggle class="lg:hidden text-2xl">☰</button><div><h2 class="text-2xl font-bold">Bank & cash accounts</h2><p class="text-sm text-slate-500">Custom fields can be renamed, reordered, added, or deleted</p></div></div><div class="text-right"><p class="text-xs text-slate-500">Total liquidity</p><p class="font-black text-xl"><?=money($pdo,$total)?></p></div></header><div class="p-5 md:p-8 max-w-7xl mx-auto"><?php if($error):?><div class="bg-rose-50 border p-4 rounded-xl mb-5"><?=h($error)?></div><?php endif;?><?php if(isset($_GET['saved'])):?><div class="bg-emerald-50 border p-4 rounded-xl mb-5">Changes saved.</div><?php endif;?><div class="grid xl:grid-cols-3 gap-7"><div class="space-y-6"><form method="post" class="bg-white border rounded-2xl p-6 space-y-4"><?=csrf_field()?><input type="hidden" name="account_id" value="<?=$editId?>"><h3 class="font-bold text-lg"><?=$editId?'Edit account':'Add account'?></h3><label class="block text-sm">Account name<input name="account_name" required value="<?=h($edit['account_name']??'')?>" class="<?=$input?>"></label><label class="block text-sm">Account type<select name="account_type" class="<?=$input?> bg-white"><?php foreach(['bank'=>'Bank','cash'=>'Cash','mobile_money'=>'Mobile money'] as $k=>$v):?><option value="<?=$k?>" <?=($edit['account_type']??'bank')===$k?'selected':''?>><?=$v?></option><?php endforeach;?></select></label><?php if(!$editId):?><label class="block text-sm">Opening balance<input type="number" step="0.01" name="initial_balance" value="0.00" class="<?=$input?>"></label><?php endif;?><?php foreach($fields as $f):?><label class="block text-sm"><?=h($f['label'])?><?php if($f['field_type']==='textarea'):?><textarea name="custom_field[<?=$f['id']?>]" class="<?=$input?>"><?=h($values[$f['id']]??'')?></textarea><?php else:?><input type="<?=$f['field_type']?>" name="custom_field[<?=$f['id']?>]" value="<?=h($values[$f['id']]??'')?>" class="<?=$input?>"><?php endif;?></label><?php endforeach;?><?php if($editId):?><label class="flex gap-2 text-sm"><input type="checkbox" name="is_active" <?=$edit['is_active']?'checked':''?>> Active account</label><?php endif;?><div class="flex gap-2"><button name="save_account" class="brand-bg text-white rounded-lg px-5 py-2.5 flex-1 font-semibold"><?=$editId?'Update':'Create'?> account</button><?php if($editId):?><a href="accounts.php" class="border rounded-lg px-4 py-2.5">Cancel</a><?php endif;?></div></form>
<section class="bg-white border rounded-2xl p-6"><h3 class="font-bold">Account field manager</h3><p class="text-sm text-slate-500 mb-4">Define the fields shown on every bank or cash account.</p><form method="post" class="grid grid-cols-2 gap-2 mb-4"><?=csrf_field()?><input name="label" required placeholder="Field label" class="border rounded px-2 py-2"><input name="field_key" placeholder="field_key (optional)" class="border rounded px-2"><select name="field_type" class="border rounded px-2 bg-white"><option value="text">Text</option><option value="textarea">Long text</option><option value="number">Number</option><option value="date">Date</option></select><input type="number" name="sort_order" value="50" class="border rounded px-2"><button name="save_field" class="col-span-2 bg-slate-900 text-white rounded py-2">Add field</button></form><?php foreach($fields as $f):?><details class="border rounded-lg p-3 mb-2"><summary class="text-sm font-semibold cursor-pointer"><?=h($f['label'])?></summary><form method="post" class="grid grid-cols-2 gap-2 mt-3"><?=csrf_field()?><input type="hidden" name="field_id" value="<?=$f['id']?>"><input name="label" value="<?=h($f['label'])?>" class="border rounded px-2"><input name="field_key" value="<?=h($f['field_key'])?>" class="border rounded px-2"><select name="field_type" class="border rounded px-2"><?php foreach(['text','textarea','number','date'] as $t):?><option <?=$f['field_type']===$t?'selected':''?>><?=$t?></option><?php endforeach;?></select><input type="number" name="sort_order" value="<?=$f['sort_order']?>" class="border rounded px-2"><button name="save_field" class="bg-slate-900 text-white rounded py-1">Update</button><button name="delete_field" onclick="return confirm('Delete this field and its saved values?')" class="border text-rose-700 rounded py-1">Delete</button></form></details><?php endforeach;?></section></div>
<section class="xl:col-span-2 grid md:grid-cols-2 gap-4 h-fit"><?php foreach($accounts as $a):?><article class="bg-white border rounded-2xl p-5 <?=$a['is_active']?'':'opacity-60'?>"><div class="flex justify-between"><div><span class="text-xs uppercase font-bold text-slate-400"><?=h(str_replace('_',' ',$a['account_type']))?></span><h3 class="font-bold text-lg"><?=h($a['account_name'])?></h3></div><a href="accounts.php?edit=<?=$a['id']?>" class="brand-text text-sm font-semibold">Edit</a></div><p class="text-2xl font-black mt-5 money"><?=money($pdo,$a['current_balance'])?></p><dl class="mt-4 border-t pt-3 text-sm space-y-2"><?php foreach(explode('|',(string)$a['custom_values']) as $pair):if(!$pair)continue;[$label,$value]=array_pad(explode('::',$pair,2),2,'');?><div class="flex justify-between gap-3"><dt class="text-slate-500"><?=h($label)?></dt><dd class="font-medium text-right break-all"><?=h($value?:'—')?></dd></div><?php endforeach;?></dl></article><?php endforeach;?></section></div></div></main><?php require_once 'includes/footer.php';?>
